iers.RestoreEquipment(e);soldiers.RestoreSoldier(new SoldierInstance(f.SoldierA,f.UnitA1,TroopDefinitionId.Create("troop-melee"),new SoldierRecruitmentProvenance(sourceA.Id,RecruitmentRecordId.Create("record-a1")),new SoldierLoadout(new[]{new WeaponSlotAssignment(WeaponSlot.Main,f.SwordA)}),CombatRoleId.Create("melee")));soldiers.RestoreSoldier(new SoldierInstance(f.SoldierB,f.UnitB1,TroopDefinitionId.Create("troop-ranged"),new SoldierRecruitmentProvenance(sourceB.Id,RecruitmentRecordId.Create("record-b1")),new SoldierLoadout(new[]{new WeaponSlotAssignment(WeaponSlot.Main,f.BowB),new WeaponSlotAssignment(WeaponSlot.Ammo,f.AmmoB)}),CombatRoleId.Create("ranged")));soldiers.RestoreSoldier(new SoldierInstance(f.SoldierMounted,f.UnitA2,TroopDefinitionId.Create("troop-mounted"),new SoldierRecruitmentProvenance(sourceA.Id,RecruitmentRecordId.Create("record-a2")),new SoldierLoadout(new[]{new WeaponSlotAssignment(WeaponSlot.Main,f.LanceMounted)},new[]{new ArmorSlotAssignment(ArmorSlot.Body,f.ArmorMounted)},mount:f.HorseMounted),CombatRoleId.Create("mounted")));f.Campaign=new CampaignRuntimeState(StableId<CampaignTag>.Create("campaign"),"0.9","battle-1",99,1,clock,new SeededRandomSource(99),characters,organizations,null,null,null,null,economy,null,military,soldiers);var graph=new BattleSectorGraph();var sa=new BattleSector(f.SectorA,new[]{BattleTerrainTag.Open},new[]{f.SideA});var sm=new BattleSector(f.SectorMiddle,new[]{BattleTerrainTag.Rough});var sb=new BattleSector(f.SectorB,new[]{BattleTerrainTag.Open},new[]{f.SideB});if(reverse){graph.Add(sb);graph.Add(sm);graph.Add(sa);}else{graph.Add(sa);graph.Add(sm);graph.Add(sb);}graph.Connect(f.SectorA,f.SectorMiddle);graph.Connect(f.SectorMiddle,f.SectorB);var ammo=new BattleAmmunitionState();ammo.Add(new BattleAmmoAllocation(f.SoldierB,AmmoFamilyId.Create("arrow"),2));f.Battle=new BattleCreationService(f.Campaign).Create(new BattleCreationRequest(BattleId.Create("battle-main"),clock.Now,new SeededRandomSource(123).CaptureState()