        private static OrganizationState Organization(string id,CharacterId commander,ArmyId army){var o=new OrganizationState(OrganizationId.Create(id),id);o.AddAssignment(new AssignmentState(AssignmentId.Create(id=="org-a"?"assignment-a":"assignment-b"),commander,OrganizationBranch.Army,"army-commander",AssignmentAuthority.FullAuthority,AssignmentTarget.Army(army),AssignmentPresence.PhysicalPresenceRequired,new WorldTimestamp(0)));return o;}
        private static RecruitmentSourceState Source(string id,CharacterId commander,OrganizationId org,AssignmentId assignment)=>new RecruitmentSourceState(RecruitmentSourceId.Create(id),RecruitmentType.Retinue,20,new RecruitmentAuthorityReference(commander,org,assignment));
        private static ArmyState Army(ArmyId id,string name,CharacterId commander,OrganizationId org,AssignmentId assignment){var a=new ArmyState(id,name,ArmyOwnerRef.Character(commander),ArmyOwnerRef.Character(commander),ArmyLocation.AtCamp(new WorldPosition(0,0)),new ArmyCommanderReference(commander,org,assignment));a.SetLifecycle(ArmyLifecycle.Active);return a;}
        private static UnitGroupState Unit(UnitGroupId id,ArmyId army,RecruitmentSourceId source,string troop,long count,CharacterId? commander=null)=>new UnitGroupState(id,army,source,troop,count,commander,new MoraleState(MoraleAssessment.Steady),new FatigueState(FatigueAssessment.Rested),new DisciplineState(DisciplineAssessment.Ordered));
        private static RecruitmentRecord Record(string id,RecruitmentSourceId source,ArmyId army,UnitGroupId unit,long count)=>new RecruitmentRecord(RecruitmentRecordId.Create(id),source,army,unit,count,new WorldTimestamp(1));
        private static TradeGoodDefinition Good(string id)=>new TradeGoodDefinition(TradeGoodId.Create(id),id,TradeGoodCategory.Military,1,false,true,false,1);
